:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #e0e0e0;
  --accent: #f5c542;
  --pixel-size: 4px;
  --border-width: 3px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image: 
    linear-gradient(45deg, var(--secondary) 25%, transparent 25%),
    linear-gradient(-45deg, var(--secondary) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--secondary) 75%),
    linear-gradient(-45deg, transparent 75%, var(--secondary) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: var(--border-width) solid var(--primary);
  box-shadow: 8px 8px 0 var(--secondary);
  padding: 24px 20px;
  width: 100%;
  max-width: 480px;
  border-radius: 0;
}

h1 {
  font-size: 1.75rem;
  text-align: center;
  margin-bottom: 24px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--primary);
  letter-spacing: 1px;
}

.input-group {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.input-group input {
  flex: 1 1 180px;
  padding: 12px;
  font-size: 1rem;
  font-family: inherit;
  background: var(--bg);
  border: var(--border-width) solid var(--secondary);
  color: var(--text);
  outline: none;
  transition: border-color 0.1s;
}

.input-group input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 20px;
  background: var(--primary);
  color: #fff;
  border: var(--border-width) solid var(--secondary);
  box-shadow: 4px 4px 0 var(--secondary);
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.pixel-btn:hover {
  background: #ff5a7a;
  box-shadow: 6px 6px 0 var(--secondary);
  transform: translate(-2px, -2px);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--secondary);
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg);
  border: var(--border-width) solid var(--secondary);
  padding: 8px 12px;
  flex-wrap: wrap;
}

.task-name {
  flex: 1 1 120px;
  word-break: break-word;
  font-size: 1rem;
}

.task-timer {
  font-family: 'Courier New', monospace;
  font-size: 1.125rem;
  font-weight: bold;
  color: var(--accent);
  min-width: 60px;
  text-align: right;
}

.task-btn {
  font-family: inherit;
  font-size: 0.875rem;
  font-weight: bold;
  padding: 8px 12px;
  background: var(--secondary);
  color: var(--text);
  border: 2px solid var(--primary);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  min-width: 60px;
}

.task-btn:hover {
  background: var(--primary);
}

.task-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 1px;
}

.task-btn:active {
  transform: scale(0.95);
}

.task-btn.start {
  background: #2e7d32;
  border-color: #1b5e20;
}

.task-btn.start:hover {
  background: #388e3c;
}

.task-btn.stop {
  background: #c62828;
  border-color: #8e0000;
}

.task-btn.stop:hover {
  background: #e53935;
}

.task-btn.remove {
  background: transparent;
  border-color: var(--primary);
  color: var(--primary);
  padding: 8px 10px;
  min-width: auto;
}

.task-btn.remove:hover {
  background: var(--primary);
  color: #fff;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px 12px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .task-item {
    padding: 6px 8px;
  }
  .task-btn {
    font-size: 0.8125rem;
    padding: 6px 8px;
  }
  .task-timer {
    font-size: 1rem;
    min-width: 50px;
  }
}

(function() {
  'use strict';

  const taskForm = document.getElementById('task-form');
  const taskInput = document.getElementById('task-input');
  const taskList = document.getElementById('task-list');

  let tasks = [];
  let runningTaskId = null;
  let timerInterval = null;

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function stopRunningTask() {
    if (runningTaskId !== null) {
      const runningTask = tasks.find(t => t.id === runningTaskId);
      if (runningTask) {
        runningTask.running = false;
        runningTask.startTime = null;
      }
      runningTaskId = null;
    }
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  }

  function startTimerLoop() {
    if (timerInterval) clearInterval(timerInterval);
    timerInterval = setInterval(() => {
      if (runningTaskId === null) return;
      const task = tasks.find(t => t.id === runningTaskId);
      if (!task || !task.running) return;
      const now = Date.now();
      task.elapsed = task.baseElapsed + Math.floor((now - task.startTime) / 1000);
      updateTaskDisplay(task);
    }, 250);
  }

  function updateTaskDisplay(task) {
    const li = taskList.querySelector(`[data-id="${task.id}"]`);
    if (!li) return;
    const timerEl = li.querySelector('.task-timer');
    if (timerEl) timerEl.textContent = formatTime(task.elapsed);
    const btn = li.querySelector('.task-btn.toggle');
    if (btn) {
      if (task.running) {
        btn.textContent = 'Stop';
        btn.classList.remove('start');
        btn.classList.add('stop');
        btn.setAttribute('aria-label', `Stop timer for ${task.name}`);
      } else {
        btn.textContent = 'Start';
        btn.classList.remove('stop');
        btn.classList.add('start');
        btn.setAttribute('aria-label', `Start timer for ${task.name}`);
      }
    }
  }

  function renderTask(task) {
    const li = document.createElement('li');
    li.className = 'task-item';
    li.dataset.id = task.id;

    const nameSpan = document.createElement('span');
    nameSpan.className = 'task-name';
    nameSpan.textContent = task.name;

    const timerSpan = document.createElement('span');
    timerSpan.className = 'task-timer';
    timerSpan.textContent = formatTime(task.elapsed);
    timerSpan.setAttribute('aria-label', `Time for ${task.name}: ${formatTime(task.elapsed)}`);

    const toggleBtn = document.createElement('button');
    toggleBtn.type = 'button';
    toggleBtn.className = 'task-btn toggle ' + (task.running ? 'stop' : 'start');
    toggleBtn.textContent = task.running ? 'Stop' : 'Start';
    toggleBtn.setAttribute('aria-label', (task.running ? 'Stop' : 'Start') + ' timer for ' + task.name);
    toggleBtn.addEventListener('click', () => toggleTask(task.id));

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'task-btn remove';
    removeBtn.textContent = '✕';
    removeBtn.setAttribute('aria-label', 'Remove task: ' + task.name);
    removeBtn.addEventListener('click', () => removeTask(task.id));

    li.appendChild(nameSpan);
    li.appendChild(timerSpan);
    li.appendChild(toggleBtn);
    li.appendChild(removeBtn);
    taskList.appendChild(li);
  }

  function addTask(name) {
    const task = {
      id: Date.now() + Math.random().toString(36).slice(2),
      name: name,
      elapsed: 0,
      baseElapsed: 0,
      running: false,
      startTime: null
    };
    tasks.push(task);
    renderTask(task);
  }

  function removeTask(id) {
    const index = tasks.findIndex(t => t.id === id);
    if (index === -1) return;
    if (runningTaskId === id) {
      stopRunningTask();
    }
    tasks.splice(index, 1);
    const li = taskList.querySelector(`[data-id="${id}"]`);
    if (li) li.remove();
  }

  function toggleTask(id) {
    const task = tasks.find(t => t.id === id);
    if (!task) return;

    if (task.running) {
      // Stop this task
      task.baseElapsed = task.elapsed;
      task.running = false;
      task.startTime = null;
      runningTaskId = null;
      if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
      }
      updateTaskDisplay(task);
    } else {
      // Stop any running task first
      if (runningTaskId !== null) {
        const prev = tasks.find(t => t.id === runningTaskId);
        if (prev) {
          prev.baseElapsed = prev.elapsed;
          prev.running = false;
          prev.startTime = null;
          updateTaskDisplay(prev);
        }
      }
      // Start this task
      task.running = true;
      task.startTime = Date.now();
      task.baseElapsed = task.elapsed;
      runningTaskId = id;
      startTimerLoop();
      updateTaskDisplay(task);
    }
  }

  taskForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = taskInput.value.trim();
    if (!name) return;
    addTask(name);
    taskInput.value = '';
    taskInput.focus();
  });

  // Cleanup on page unload (optional)
  window.addEventListener('beforeunload', () => {
    if (timerInterval) clearInterval(timerInterval);
  });
})();
